function draw() {
  ctx.clearRect(0, 0, width, height);
  // Planet
  ctx.fillStyle = '#4a6';
  ctx.beginPath();
  ctx.arc(planet.x, planet.y, planet.r, 0, Math.PI * 2);
  ctx.fill();
  // Satellite
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.arc(sat.x, sat.y, sat.size, 0, Math.PI * 2);
  ctx.fill();
  // Meteors
  ctx.fillStyle = '#a33';
  for (const m of meteors) {
    ctx.beginPath();
    ctx.arc(m.x, m.y, m.r, 0, Math.PI * 2);
    ctx.fill();
  }
  // Game over overlay
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = '#fff';
    ctx.font = '36px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', width / 2, height / 2);
  }
}

input.newString:
function draw() {
  // Background space gradient
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, '#001');
  bgGrad.addColorStop(1, '#003');
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // Stars
  ctx.fillStyle = '#fff';
  for (const s of stars) {
    ctx.beginPath();
    ctx.arc(s.x, s.y, s.r, 0, Math.PI * 2);
    ctx.fill();
  }

  // Planet with gradient
  ctx.fillStyle = planetGradient;
  ctx.beginPath();
  ctx.arc(planet.x, planet.y, planet.r, 0, Math.PI * 2);
  ctx.fill();

  // Satellite with glow
  const satGrad = ctx.createRadialGradient(sat.x, sat.y, sat.size * 0.2, sat.x, sat.y, sat.size * 2);
  satGrad.addColorStop(0, '#fff');
  satGrad.addColorStop(1, 'rgba(255,255,255,0)');
  ctx.fillStyle = satGrad;
  ctx.beginPath();
  ctx.arc(sat.x, sat.y, sat.size * 2, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = '#fff';
  ctx.beginPath();
  ctx.arc(sat.x, sat.y, sat.size, 0, Math.PI * 2);
  ctx.fill();

  // Meteors with tail gradient
  for (const m of meteors) {
    const trailGrad = ctx.createRadialGradient(m.x, m.y, 0, m.x, m.y, m.r * 3);
    trailGrad.addColorStop(0, 'rgba(255,100,100,0.8)');
    trailGrad.addColorStop(1, 'rgba(255,100,100,0)');
    ctx.fillStyle = trailGrad;
    ctx.beginPath();
    ctx.arc(m.x, m.y, m.r * 3, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#a33';
    ctx.beginPath();
    ctx.arc(m.x, m.y, m.r, 0, Math.PI * 2);
    ctx.fill();
  }

  // Game over overlay
  if (gameOver) {
    ctx.fillStyle = 'rgba(0,0,0,0.6)';
    ctx.fillRect(0, 0, width, height);
    ctx.fillStyle = '#fff';
    ctx.font = '36px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('Game Over', width / 2, height / 2);
  }
}

